class PythonCodePrinter(CodePrinter):
    """Printer for generating Python code, that is executable.

    Examples
    ========

    >>> from sympy import symbols, pi, sin
    >>> from sympy.printing.pycode import pycode
    >>> x = symbols('x')
    >>> pycode(sin(x)*pi) #doctest: +SKIP
    'math.sin(x)*math.pi'

    """
    printmethod = "pycode"

    def __init__(self, settings=None):
        super().__init__(settings)
        # Add pycode specific initialization here. We need to set the default
        # pycode printer to use the default printers.
        # XXX: this should be done in a more object oriented way not like this.
        if not hasattr(self, 'code_printers'):
            self.code_printers = {}
        # XXX:
        if not hasattr(self, 'known_functions'):
            self.known_functions = [
                "acos", "acosh", "asin", "asinh", "atan", "atanh",
                "cos", "cosh", "log", "sec", "sech", "sin", "sinh",
                "tan", "tanh", "atan2", "exp", "log", "sqrt",
                "I", "E", "pi",
            ]
            self.unknown_functions = [
                "apart", "cancel", "cos", "Derivative", "diff",
                "exp", "Integral", "integrate", "log", "principal_value",
                "rad", "roots", "sin", "solve", "subsections", "sum",
                "total_degree", "transpose", "Wild", "WildFunction",
                "zeta", "asec", "csch", "expreivatives", "Im", "re",
                "sech", "sin", "tan", "tanh", "csc", "cot", "coth",
                "Max", "Min",
            ]

    def _print_Add(self, expr):
        if expr.is_Add:
            # use a standard pretty-printer for Add terms.
            return "(" + ")".join([self._print(arg) for arg in expr.args]).replace(')(', '+')
        else:
            return self._print(expr)

    def _print_Mul(self, expr):
        if expr.is_Mul:
            # use a standard pretty-printer for Mul terms.
            return "(" + ")".join([self._print(arg) for arg in expr.args]).replace(')(', '*')
        else:
            return self._print(expr)

    def _print_Pow(self, expr, rational=False):
        if expr.is_Pow:
            base = self._print(expr.base)
            exponent = self._print(expr.exp)
            if exponent.startswith("-"):
                return "(" + base + "**(" + exponent + "))"
            else:
                return base + "**" + exponent
        else:
            return self._print(expr)

    def _print_Rational(self, expr, rational=False):
        if expr.q == 1:
            return str(expr.p)
        if self.settings['rational']:
            return "Rational(" + str(expr.p) + ", " + str(expr.q) + ")"
        if expr.q == -1:
            return "-" + str(expr.p)
        return str(expr.p) + "/" + str(expr.q)

    def _print_Integer(self, expr):
        return str(expr.p)

    def _print_Float(self, expr):
        return str(expr.evalf()) # This does not use the settings

    def _print_Function(self, expr):
        func = expr.__class__.__name__  # Use __class__.__name__ to get the name of the function
        if func in self.known_functions:
            return self.known_functions[func] + "(" + ", ".join([
                self._print(arg) for arg in expr.args
            ]) + ")"
        elif func in self.unknown_functions:
            return func + "(" + ", ".join([
                self._print(arg) for arg in expr.args
            ]) + ")"
        else:
            raise NotImplementedError(
                "No code printer registered for %s" % func
            )

    # --- Functions that should be printed as built-in python functions

    def _print_Abs(self, expr):
        return "abs(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_Max(self, expr):
        # This is for SymPy's Max function, not Python's max().
        # We need to convert it to Python's max().
        if len(expr.args) == 1:
            return self._print(expr.args[0])
        else:
            return "max(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_Min(self, expr):
        # This is for SymPy's Min function, not Python's min().
        # We need to convert it to Python's min().
        if len(expr.args) == 1:
            return self._print(expr.args[0])
        else:
            return "min(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _umenical_repr(self, expr):
        # This is necessary for generating a unified representation
        # for different types of expressions. All expressions will
        # be converted to their string representation.
        return str(expr)

    def _print_Tuple(self, expr):
        return "(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_List(self, expr):
        return "[" + ", ".join([self._print(arg) for arg in expr.args]) + "]"

    def _print_Set(self, expr):
        return "{" + ", ".join([self._print(arg) for arg in expr.args]) + "}"

    def _print_FrozenSet(self, expr):
        return "frozenset({" + ", ".join([self._print(arg) for arg in expr.args]) + "})"

    def _print_Weighted(self, expr):
        return self._print(expr.args[0])

    def _print_Equality(self, expr):
        return self._print(expr.args[0]) + " == " + self._print(expr.args[1])

    def _print_Unequality(self, expr):
        return self._print(expr.args[0]) + " != " + self._print(expr.args[1])

    def _print_dict(self, expr):
        return "{\"" + str(expr).replace(": ", "\": ") + "}"

    def _print_complex(self, z):
        return str(z.real) + " + " + str(z.imag) + "j"

    def _print_ImaginaryUnit(self, expr):
        return str(expr.n())

    def _print_Exp(self, expr):
        if APRINTER.convert_dict.get('exp'):
            return APRINTER.convert_dict['exp']
        return "exp(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_log(self, expr):
        return "log(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_sin(self, expr):
        return "sin(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_cos(self, expr):
        return "cos(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_tan(self, expr):
        return "tan(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_cot(self, expr):
        return "cot(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_csc(self, expr):
        return "csc(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_sec(self, expr):
        return "sec(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_tanh(self, expr):
        return "tanh(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_sinh(self, expr):
        return "sinh(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_cosh(self, expr):
        return "cosh(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_ASinh(self, expr):
        return "asinh(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_ACosh(self, expr):
        return "acosh(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_ATanh(self, expr):
        return "atanh(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_ASin(self, expr):
        return "asin(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_ACos(self, expr):
        return "acos(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_ATan(self, expr):
        return "atan(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_ATan2(self, expr):
        return "atan2(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_Sign(self, expr):
        return "sign(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_Piecewise(self, piecewise):
        if len(piecewise.args) == 2 and piecewise.args[1] == 0:
            return "(" + self._print(piecewise.args[0]) + ") if " + self._print(piecewise.args[1]) + " else 0"
        else:
            if len(piecewise.args) == 0:
                return "None"
            if len(piecewise.args) == 1:
                return self._print(piecewise.args[0])
            # Recursively print the piecewise structure
            result = self._print(piecewise.args[0])
            for i in range(1, len(piecewise.args)):
                current_arg = piecewise.args[i]
                if current_arg.args[1] == 0:
                    result += " if " + self._print(current_arg.args[0]) + " else " + self._print(current_arg.args[1])
                else:
                    result += " if " + self._print(current_arg.args[0]) + " else " + self._print(current_arg.args[1])
            return result

    def _print_And(self, expr):
        if len(expr.args) == 1:
            return self._print(expr.args[0])
        elif len(expr.args) == 0:
            return "True"
        else:
            return "(" + " and ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_Or(self, expr):
        if len(expr.args) == 1:
            return self._print(expr.args[0])
        elif len(expr.args) == 0:
            return "False"
        else:
            return "(" + " or ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_Boolean(self, expr):
        return str(expr)

    def _print_BooleanTrue(self, expr):
        return "True"

    def _print_BooleanFalse(self, expr):
        return "False"

    def _print_Matrix(self, expr):
        if expr.rows == 1 and expr.cols == 1:
            return self._print(expr[0, 0])
        else:
            rows = ["["]
            for i in range(expr.rows):
                rows.append("  [" + ", ".join([self._print(expr[i, j]) for j in range(expr.cols)]) + "]")
            rows.append("]")
            return "\n".join(rows)

    def _print_MatrixElement(self, expr):
        return self._print(expr.parent) + "[" + str(expr.i) + ", " + str(expr.j) + "]"

    def _print_Add_wrap(self, expr):
        return self._print(expr)

    def _print_Mul_wrap(self, expr):
        return self._print(expr)

    def _print_Pow_wrap(self, expr):
        return self._print(expr)

    # --- Methods specifically for Min and Max ---
    def _print_Min(self, expr):
        return "min(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"

    def _print_Max(self, expr):
        return "max(" + ", ".join([self._print(arg) for arg in expr.args]) + ")"


